mapper.select:
SELECT cs.id, cs.user_id AS userId, su.user_name AS userName, cs.session_title AS sessionTitle, cs.agent_id AS agentId, cs.model_id AS modelId, cs.status, cs.last_message_at AS lastMessageAt, cs.message_count AS messageCount, cs.input_tokens AS inputTokens, cs.output_tokens AS outputTokens, cs.deduct_tokens AS deductTokens, cs.conversation_id AS conversationId, cs.update_time AS updateTime FROM chat_session cs LEFT JOIN sys_user su ON su.user_id = cs.user_id
AND cs.id = #{bo.id}
AND cs.user_id = #{bo.userId}
AND su.user_name LIKE CONCAT('%', #{bo.userName}, '%')
AND cs.session_title LIKE CONCAT('%', #{bo.sessionTitle}, '%')
AND cs.agent_id = #{bo.agentId}
AND cs.model_id = #{bo.modelId}
AND cs.status = #{bo.status}
AND cs.conversation_id LIKE CONCAT('%', #{bo.conversationId}, '%')
ORDER BY cs.last_message_at DESC, cs.id DESC

mapper.update:
UPDATE chat_session SET session_title = #{sessionTitle}, update_time = #{updateTime}
WHERE id = #{id}
AND user_id = #{ownerUserId}

UPDATE chat_session SET status = #{status}, update_time = #{updateTime}
WHERE id = #{id}
AND user_id = #{ownerUserId}
